"""Chemistry of a row of gas cells, without hydrodynamics.

The smallest use of the chemistry module: the 16-species carbox network of
``external/carbox/data/simple_latent_tgas.csv`` with thermochemistry, advanced in every
cell by the two implicit solvers of the module,

* the vmapped Diffrax Kvaerno5 (the default), and
* the per-cell Rosenbrock23 Warp kernel generated by gradsolve from the same right-hand side,

and a comparison of the two results. Run it from the repository root after the steps of
"Chemistry quick start" in the README:

    python examples/chemistry_cells.py                # on the CPU, a minute or two
    python examples/chemistry_cells.py --no-kernel    # Kvaerno5 only (no warp / gradsolve needed)
    python examples/chemistry_cells.py --cells 4096 --steps 5

The cells span ``n_H`` = 10 to 1e4 cm^-3 at 100 K and start atomic (H, C+, O, and the
electrons of C+), so molecular hydrogen forms on the grains during the run, the faster the
denser the cell.
"""

import argparse
import os
import time

import jax

jax.config.update("jax_enable_x64", True)

import jax.numpy as jnp
import numpy as np

from astronomix import (
    SimulationConfig,
    SimulationParams,
    construct_primitive_state,
    finalize_config,
    get_registered_variables,
)
from astronomix._modules._chemistry._chemistry import make_vector_field, update_chemistry
from astronomix._modules._cooling._cooling import (
    get_pressure_from_temperature,
    get_temperature_from_pressure,
)
from astronomix.option_classes.simulation_config import FINITE_VOLUME, NATIVE_JAX
from astronomix.setup_helpers import build_chemistry_from_network_file

REPOSITORY_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DEFAULT_NETWORK = os.path.join(
    REPOSITORY_ROOT, "external", "carbox", "data", "simple_latent_tgas.csv"
)

# Code units of this example: density in m_p cm^-3, temperature in K, time in Myr.
NUMBER_DENSITY_UNIT_CGS = 1.0
TEMPERATURE_UNIT_KELVIN = 1.0
TIME_UNIT_SECONDS = 3.15576e13
GAMMA = 5.0 / 3.0

# Abundances per hydrogen nucleus at the start; every other species starts at 1e-12.
INITIAL_ABUNDANCES = {"H": 1.0, "C+": 1.4e-4, "O": 3.2e-4, "E": 1.4e-4}
INITIAL_TEMPERATURE_KELVIN = 100.0


def build(network_csv, num_cells, use_kernel, rtol, atol):
    """Return the initial state and what ``update_chemistry`` needs to advance it."""
    chemistry_config, chemistry_params, species_names = build_chemistry_from_network_file(
        network_csv,
        "latent_tgas",
        number_density_unit_cgs=NUMBER_DENSITY_UNIT_CGS,
        temperature_unit_kelvin=TEMPERATURE_UNIT_KELVIN,
        time_unit_seconds=TIME_UNIT_SECONDS,
        cosmic_ray_rate=3.0e-17,
        fuv_field=1.0e-4,
        visual_extinction=2.0,
        thermochemistry=True,
        cooling_courant=10.0,
        absolute_tolerance=atol,
        relative_tolerance=rtol,
        max_steps=2048,
    )

    if use_kernel:
        # The kernel is generated from the same right-hand side the Kvaerno5 solver
        # integrates (species + temperature), then handed to the module as a callable.
        from astronomix._modules._chemistry._warp_stiff import build_fused_core_solver

        cc, cp = chemistry_config, chemistry_params
        vector_field = make_vector_field(
            cp.network, cp.rate_modifier_a, cp.rate_modifier_b, cp.cosmic_ray_rate, cp.fuv_field,
            cp.visual_extinction, cc.thermochemistry, GAMMA, cp.dust_to_gas_ratio,
            cp.hydrogen_molecule_formation_rate_coefficient, cc.hydrogen_index,
            cc.molecular_hydrogen_index, cc.electron_index, cc.atomic_oxygen_index,
            cc.ionized_hydrogen_index, cc.helium_index, cc.ionized_carbon_index, cc.co_cooling,
            cc.carbon_monoxide_index, cp.co_cooling_table, cp.co_cooling_bounds,
        )
        solver = build_fused_core_solver(
            vector_field, cc.number_of_chemical_species + 1,
            rtol=float(cp.rtol), atol=float(cp.atol), max_steps=cc.max_steps,
            cache_key="example-chemistry-cells",
        )
        chemistry_config = chemistry_config._replace(stiff_core_solver="warp", stiff_core_fn=solver)

    config = SimulationConfig(
        dimensionality=1,
        solver_mode=FINITE_VOLUME,
        backend=NATIVE_JAX,
        box_size=1.0,
        num_cells=num_cells,
        progress_bar=False,
        chemistry_config=chemistry_config,
    )
    params = SimulationParams(t_end=1.0, gamma=GAMMA, chemistry_params=chemistry_params)
    registered_variables = get_registered_variables(config)

    hydrogen_mass_fraction = chemistry_params.hydrogen_mass_fraction
    metal_mass_fraction = chemistry_params.metal_mass_fraction
    hydrogen_nuclei = jnp.logspace(1.0, 4.0, num_cells)  # n_H [cm^-3]
    density = hydrogen_nuclei / hydrogen_mass_fraction  # rho / m_p [cm^-3]
    pressure = get_pressure_from_temperature(
        density,
        jnp.full(num_cells, INITIAL_TEMPERATURE_KELVIN / TEMPERATURE_UNIT_KELVIN),
        hydrogen_mass_fraction,
        metal_mass_fraction,
    )
    state = construct_primitive_state(
        config=config,
        registered_variables=registered_variables,
        density=density,
        velocity_x=jnp.zeros(num_cells),
        gas_pressure=pressure,
    )
    # The species block holds number densities in code units (here cm^-3).
    start = registered_variables.chemistry_species_index
    for index, name in enumerate(species_names):
        abundance = INITIAL_ABUNDANCES.get(name, 1.0e-12)
        state = state.at[start + index].set(abundance * hydrogen_nuclei)

    config = finalize_config(config, state.shape)
    return state, config, params, registered_variables, tuple(species_names), np.asarray(hydrogen_nuclei)


def run(network_csv, num_cells, num_steps, time_step, use_kernel, rtol, atol):
    """Advance the cells ``num_steps`` times; return abundances per H nucleus and temperature."""
    state, config, params, registered_variables, names, hydrogen_nuclei = build(
        network_csv, num_cells, use_kernel, rtol, atol
    )
    start_time = time.perf_counter()
    for step in range(num_steps):
        state = update_chemistry(
            state, registered_variables, config.chemistry_config, params, time_step
        )
        if step == 0:
            jax.block_until_ready(state)
            first_step = time.perf_counter() - start_time
    jax.block_until_ready(state)
    elapsed = time.perf_counter() - start_time

    start = registered_variables.chemistry_species_index
    species = np.asarray(state[start : start + len(names)])
    chemistry_params = params.chemistry_params
    temperature = TEMPERATURE_UNIT_KELVIN * np.asarray(
        get_temperature_from_pressure(
            state[registered_variables.density_index],
            state[registered_variables.pressure_index],
            chemistry_params.hydrogen_mass_fraction,
            chemistry_params.metal_mass_fraction,
        )
    )
    return species / hydrogen_nuclei, temperature, names, hydrogen_nuclei, first_step, elapsed


def report(label, abundances, temperature, names, hydrogen_nuclei):
    columns = ("H", "H2", "E", "C+", "C", "CO")
    print(f"\n{label}")
    print("   n_H [cm^-3]     T [K] " + "".join(f"{'x(' + name + ')':>11s}" for name in columns))
    shown = np.unique(np.linspace(0, len(hydrogen_nuclei) - 1, min(8, len(hydrogen_nuclei))).astype(int))
    for cell in shown:
        values = "".join(f"{abundances[names.index(name), cell]:11.3e}" for name in columns)
        print(f"   {hydrogen_nuclei[cell]:11.3e} {temperature[cell]:9.2f} {values}")


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    parser.add_argument("--network", default=DEFAULT_NETWORK, help="carbox network file (latent_tgas format)")
    parser.add_argument("--cells", type=int, default=16)
    parser.add_argument("--steps", type=int, default=20)
    parser.add_argument("--time-step", type=float, default=0.05, help="length of a step [Myr]")
    parser.add_argument("--rtol", type=float, default=1.0e-6)
    parser.add_argument("--atol", type=float, default=1.0e-12)
    parser.add_argument("--no-kernel", action="store_true", help="skip the Warp kernel (gradsolve, warp-lang)")
    arguments = parser.parse_args()

    if not os.path.exists(arguments.network):
        raise SystemExit(
            f"network file not found: {arguments.network}\n"
            "run 'git submodule update --init' in the repository, or pass --network"
        )
    print(f"network: {arguments.network}")
    print(f"devices: {jax.devices()}")
    print(
        f"{arguments.cells} cells, {arguments.steps} steps of {arguments.time_step} Myr "
        f"({arguments.steps * arguments.time_step:g} Myr), rtol {arguments.rtol:g}, atol {arguments.atol:g}"
    )
    common = (arguments.network, arguments.cells, arguments.steps, arguments.time_step)
    tolerances = (arguments.rtol, arguments.atol)

    reference, temperature, names, hydrogen_nuclei, first, elapsed = run(*common, False, *tolerances)
    report("Diffrax Kvaerno5 (vmapped)", reference, temperature, names, hydrogen_nuclei)
    print(f"   first step {first:.1f} s (compilation included), all steps {elapsed:.1f} s")
    if arguments.no_kernel:
        return

    kernel, kernel_temperature, _, _, first, elapsed = run(*common, True, *tolerances)
    report("Rosenbrock23 Warp kernel (gradsolve), one thread per cell", kernel, kernel_temperature, names, hydrogen_nuclei)
    print(f"   first step {first:.1f} s (kernel build included), all steps {elapsed:.1f} s")

    significant = reference > 1.0e-10
    difference = np.abs(np.log10(kernel[significant] / reference[significant]))
    temperature_difference = np.abs(kernel_temperature / temperature - 1.0)
    print(
        f"\nkernel against Kvaerno5: largest |dlog10 x| {difference.max():.1e} dex over the abundances above 1e-10, "
        f"largest relative temperature difference {temperature_difference.max():.1e}"
    )


if __name__ == "__main__":
    main()
